"""FastAPI 入口:薄壳。这一层只做三件事:校验、读写历史、调主循环。
所有业务逻辑住在 agent.handle_message——API 层永远不该长出 if 业务分支。"""
from contextlib import asynccontextmanager

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

from atlas import agent, db
from atlas.guardrails import JailbreakBlocked


@asynccontextmanager
async def lifespan(_: FastAPI):
    db.init_pool()
    yield


app = FastAPI(title="ATLAS Support Agent", version="1.0", lifespan=lifespan)


class ChatIn(BaseModel):
    session_id: str = Field(min_length=8, max_length=64)
    message: str = Field(min_length=1, max_length=4000)


@app.post("/v1/chat")
def chat(body: ChatIn):
    history = db.recent_messages(body.session_id)
    try:
        result = agent.handle_message(body.session_id, body.message, history)
    except JailbreakBlocked as err:
        raise HTTPException(status_code=400, detail=str(err)) from err
    db.append_message(body.session_id, "user", body.message)
    db.append_message(body.session_id, "assistant", result["answer"])
    return result


@app.get("/healthz")
def healthz():
    return {"ok": True}

