"""FastAPI webhook 入口:验签 → 过滤 → 幂等 → 入队,然后立刻返回。"""
import json

from fastapi import FastAPI, HTTPException, Request

from sentinel import queue
from sentinel.config import settings
from sentinel.dedupe import CommentStore
from sentinel.github import verify_signature

app = FastAPI(title="SENTINEL Code Review Agent")
store = CommentStore()


@app.on_event("startup")
def _boot():
    queue.start(2)


@app.post("/webhook")
async def webhook(request: Request):
    body = await request.body()
    if not verify_signature(body, request.headers.get("x-hub-signature-256")):
        raise HTTPException(status_code=401, detail="bad signature")

    if request.headers.get("x-github-event") != "pull_request":
        return {"ok": True, "ignored": "event"}

    payload = json.loads(body)
    if payload.get("action") not in ("opened", "synchronize"):
        return {"ok": True, "ignored": payload.get("action")}

    # 幂等:GitHub 是 at-least-once 投递,同一 delivery 可能到达多次
    delivery = request.headers.get("x-github-delivery", "")
    if store.seen("_deliveries", delivery):
        return {"ok": True, "dedup": True}
    store.record("_deliveries", delivery, "")

    queue.enqueue(payload)          # 立刻入队返回,审查异步跑
    return {"ok": True, "queued": True}


@app.get("/healthz")
def healthz():
    return {"ok": True, "queue_size": queue.size()}
